# Let's manually implement the basic functionality we need
def find_changed_pairs(inputs, outputs):
    """Find pairs where input differs from output"""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit needed to transform s_in to s_out"""
    # Simple approach: find first differing position and determine what needs to change
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    pos = -1
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            pos = i
            break

    if pos == -1:
        # Strings are identical up to min length, check if one is longer
        if len(s_in) == len(s_out):
            return None  # No difference
        else:
            pos = min_len

    # Determine what to replace
    if len(s_in) > len(s_out) and pos < len(s_out):
        # Deletion case
        old_sub = s_in[pos]
        new_sub = ""
    elif len(s_in) < len(s_out) and pos < len(s_in):
        # Insertion case  
        old_sub = ""
        new_sub = s_out[pos]
    elif len(s_in) == len(s_out):
        # Substitution case
        old_sub = s_in[pos]
        new_sub = s_out[pos]
    else:
        # Mixed case - let's be more careful
        # For now, let's look at the whole string
        if len(s_in) > len(s_out):
            old_sub = s_in[pos:pos+1]
            new_sub = ""
        else:
            old_sub = ""
            new_sub = s_out[pos:pos+1]

    return (old_sub, new_sub, pos)

# Test with our data
inputs = ['zhihxc', 'jez', 'agfhjv', 'figdi', 'uzkx']
outputs = ['zhkhavbc', 'kzuez', 'ackfhkzuuhavb', 'fkckdk', 'uzkavb']

changed = find_changed_pairs(inputs, outputs)
print("Changed pairs:")
for idx, s_in, s_out in changed:
    print(f"  {idx}: '{s_in}' -> '{s_out}'")

# Analyze first few changes
for i, (idx, s_in, s_out) in enumerate(changed[:3]):
    edit = find_minimal_edit(s_in, s_out)
    print(f"  Edit {i}: {edit}")

