    min_len = min(len(s_in), len(s_out))
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if insertion, deletion, or substitution
            if len(s_in) > len(s_out):
                # Deletion
                return (s_in[i], "", i)
            elif len(s_in) < len(s_out):
                # Insertion  
                return ("", s_out[i], i)
            else:
                # Substitution
                return (s_in[i], s_out[i], i)

    # If we reach here, one string is longer
    if len(s_in) > len(s_out):
        return (s_in[min_len], "", min_len)
    elif len(s_in) < len(s_out):
        return ("", s_out[min_len], min_len)
    else:
        return None  # No difference

def propose_rule_candidates(s_in, s_out):
    # Simple approach: return the minimal edit as a candidate rule
    edit = find_minimal_edit(s_in, s_out)
    if edit:
        old_sub, new_sub, pos = edit
        return [(old_sub, new_sub)]
    return []

